window.FILM_WORK_PROMPTS={"work_id":"src-7627118d53bd4cf9","records":[{"work_id":"src-7627118d53bd4cf9","frame_id":"FG-c18254b041eac926","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (630).jpg","source_page":"https://film-grab.com/2015/06/19/lost-river/","scene":"一名身穿背心的男子在户外行走，肩上扛着巨大的行李袋。背景是色彩鲜艳的青色和紫红色砖墙建筑，左下角有一个黄色消防栓。","analysis":"画面采用平视视角，人物位于画面中央偏左，全身可见。背景建筑占据画面上半部分，色彩对比强烈，左侧为青色，右侧为紫红色，中间有绿色门框。光线从右侧照射，人物和建筑投下阴影，明暗对比明显。","prompt":"一名年轻男子在户外行走，身穿白色背心和蓝色牛仔裤，肩上扛着一个巨大的灰色行李袋，袋中露出红色和白色的衣物。背景是两栋色彩鲜艳的建筑，左侧为青色砖墙，右侧为紫红色砖墙，中间有一扇绿色的门，门上方有数字17499。左下角有一个黄色的消防栓。阳光从右侧照射，在地面和墙面上投下阴影，色彩饱和度高，画面具有强烈的视觉冲击力。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:11:41-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/07 (630).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.515,"observed_resolution":"normal","observation_limits":[],"id":"VP-83b5600f75bcd5d5","origin":"visual"},{"work_id":"src-7627118d53bd4cf9","frame_id":"FG-08108c3dbc4da0c8","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (644).jpg","source_page":"https://film-grab.com/2015/06/19/lost-river/","scene":"画面主体为一名短发人物的背影，仅可见头部与肩部轮廓。人物面向前方，背景是大面积模糊的橙黄色亮区，呈现出强烈的逆光剪影效果。","analysis":"构图采用中心对称，人物头部位于画面正中，形成黑色剪影。人物仅露出后脑勺、双耳及肩颈部分，身体其余部分不可见。背景为极度虚化的暖色光斑，与前景深色人物形成极高对比。光线主要来自人物正前方，勾勒出头部边缘的微弱轮廓光，整体色调由深黑过渡到亮橙黄。","prompt":"画面中心呈现一名短发人物的背影剪影，仅可见后脑勺、双耳及肩颈部位，人物面向前方。背景是大面积模糊的橙黄色亮区，光斑柔和且虚化严重，营造出强烈的逆光氛围。前景人物呈深黑色，与背景的高亮暖色形成鲜明对比，头部边缘有微弱轮廓光。整体色调以黑、橙、黄为主，景深极浅，焦点集中在人物头部轮廓上，背景细节完全不可辨识，呈现出一种静谧而神秘的视觉感受。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:11:49-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/20 (644).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.547,"observed_resolution":"normal","observation_limits":[],"id":"VP-a0be61b27a036c80","origin":"visual"},{"work_id":"src-7627118d53bd4cf9","frame_id":"FG-4768fa43be0ff821","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (641).jpg","source_page":"https://film-grab.com/2015/06/19/lost-river/","scene":"两名身穿深色裙装的人物并排站立在紫色光笼罩的隧道中央，头顶悬挂着垂直排列的圆形光源，地面与墙壁呈现光滑反光质感。","analysis":"画面采用严格的中心对称构图，人物位于画面正中偏下位置，全身可见但细节模糊。环境占据画面绝大部分，形成强烈的纵深感。顶部光源垂直向下延伸，形成明暗对比。整体色调为高饱和度的紫色，光线柔和且均匀，营造出一种超现实的氛围。","prompt":"在充满浓郁紫色氛围的封闭隧道空间内，两名身穿深色裙装的人物并排站立于画面中央，全身轮廓清晰可见。隧道顶部悬挂着一排垂直向下的圆形发光球体，光线在光滑的地面和墙壁上投射出柔和的紫色反光。环境比例宏大，人物在空间中显得渺小，整体画面呈现出一种静谧、神秘且带有科幻感的视觉风格，光影层次丰富，色彩高度统一。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:11:55-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/33 (641).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.335,"observed_resolution":"normal","observation_limits":[],"id":"VP-202dd7249b15a1e3","origin":"visual"},{"work_id":"src-7627118d53bd4cf9","frame_id":"FG-f32eee587e9f8576","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (628).jpg","source_page":"https://film-grab.com/2015/06/19/lost-river/","scene":"昏暗室内，一名红发女子坐在桌前，双臂交叉，神情凝重地望向右侧，右下角有明亮的烛火照亮她的面部。","analysis":"画面采用低调照明，大面积黑暗背景中，人物位于右侧三分之一处。可见人物上半身，头部至腰部，双臂交叉于胸前。右下角的烛火是主要光源，暖黄色的光线从右下方投射，照亮了女子的面部、颈部和手臂，形成强烈的明暗对比。背景几乎全黑，仅左侧隐约可见椅背轮廓。","prompt":"昏暗的室内场景，一名红发女子坐在桌前，身穿深蓝色V领上衣，双臂交叉抱在胸前，神情严肃地望向画面右侧。右下角有几支燃烧的蜡烛，发出明亮的暖黄色光芒，照亮了女子的面部和上半身，形成强烈的明暗对比。背景几乎全黑，左侧隐约可见一把椅子的靠背轮廓。整体氛围压抑而神秘，光线集中在人物面部和烛火区域，其余部分隐没在黑暗中。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:12:02-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/46 (628).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.56,"observed_resolution":"normal","observation_limits":[],"id":"VP-468ea784c4ba3c20","origin":"visual"},{"work_id":"src-7627118d53bd4cf9","frame_id":"FG-c152adeaff15097a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (573).jpg","source_page":"https://film-grab.com/2015/06/19/lost-river/","scene":"画面主体为一名深色剪影人物，位于紫色灯光笼罩的狭长走廊中央。人物呈奔跑或快速移动姿态，四肢张开，背景是延伸的通道与两侧墙壁。","analysis":"构图采用中心透视，走廊线条向远处汇聚。人物全身可见，呈黑色剪影，占据画面中心约三分之一区域。视角平视，明暗对比强烈，人物处于背光阴影中。环境被浓郁的紫色光笼罩，两侧墙壁上有数个明亮的圆形光源，地面有反光，营造出神秘、紧张的氛围。","prompt":"这是一张充满神秘感的紫色调画面，场景设定在一条狭长且深邃的室内走廊中。画面中央是一个全黑的人物剪影，正处于奔跑或快速移动的状态，四肢大幅度张开，身体前倾，呈现出强烈的动态感。走廊两侧墙壁上分布着数个明亮的圆形光源，散发出耀眼的紫粉色光芒，照亮了光滑的地面并产生倒影。整体光线昏暗，以紫色和洋红色为主色调，人物与背景形成鲜明的明暗对比，营造出一种紧张、悬疑且带有科幻色彩的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-09T13:12:09-07:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/59 (573).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.455,"observed_resolution":"normal","observation_limits":[],"id":"VP-636cb85712970cf0","origin":"visual"},{"work_id":"src-7627118d53bd4cf9","frame_id":"FG-6d9d5515f4f26d87","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (630).jpg","source_page":"https://film-grab.com/2015/06/19/lost-river/","scene":"一名身穿白T恤的年轻男子站在户外，肩扛一个巨大的灰红相间编织袋，回头看向镜头。背景是荒废的红砖公寓楼和杂草丛生的空地，左下角有一团正在燃烧的物体。","analysis":"画面采用平视视角，人物位于左侧三分之一处，身体呈侧身站立姿态，头部回转面向镜头。人物上半身及大腿部分可见，被巨大的行李袋遮挡了部分躯干。背景建筑占据右上方大面积，天空云层丰富。光线为自然日光，色彩饱和度适中，红砖墙与绿色植被形成对比，左下角的火焰提供了暖色点缀。","prompt":"一名年轻男子站在户外空地上，身穿白色短袖T恤，肩上扛着一个巨大的灰红色编织袋，袋子体积庞大，几乎遮挡了人物的下半身。男子侧身站立，头部回转看向镜头，神情略显凝重。背景是一栋废弃的红砖多层公寓楼，窗户空洞，墙面斑驳。地面杂草丛生，左下角有一团正在燃烧的物体，火焰呈橙黄色。天空多云，光线明亮，整体色调自然写实，呈现出一种荒凉的城市边缘氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:17:43+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/08 (630).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.519,"observed_resolution":"normal","observation_limits":[],"id":"VP-dcfd06b96f37d540","origin":"visual"},{"work_id":"src-7627118d53bd4cf9","frame_id":"FG-ea37b58b1c0964a1","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (644).jpg","source_page":"https://film-grab.com/2015/06/19/lost-river/","scene":"昏暗暮色中，一名短发男子仰头张嘴，面部轮廓在深蓝天空背景下呈现剪影效果，下方是模糊的深色树丛剪影。","analysis":"画面采用低角度仰拍，人物头部及颈部占据画面右侧约三分之一区域，面部朝向右上方。背景为大面积灰蓝色云层，下方横亘着模糊的黑色树冠轮廓。光线极暗，人物面部仅保留微弱轮廓光，整体呈现高对比度的剪影效果，色彩以冷调蓝灰与深黑为主。","prompt":"低角度仰拍视角，昏暗暮色环境。画面右侧前景为一名短发男子的头部与颈部剪影，他仰头面向右上方，嘴巴大张，面部轮廓在微弱光线下隐约可见。背景占据画面大部分区域，呈现灰蓝色的阴沉云层，下方边缘分布着模糊的黑色树丛剪影。整体色调为冷调蓝灰与深黑，光线极暗，人物与背景形成强烈明暗对比，营造出压抑、沉重的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:17:51+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/21 (644).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.524,"observed_resolution":"normal","observation_limits":[],"id":"VP-c62be403225bec35","origin":"visual"},{"work_id":"src-7627118d53bd4cf9","frame_id":"FG-442da5fee511a012","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (641).jpg","source_page":"https://film-grab.com/2015/06/19/lost-river/","scene":"昏暗室内，两名女性人物分列左右，中间立着紫色发光人形轮廓，上方是大面积紫色发光天花板，四周环境漆黑。","analysis":"构图呈对称布局，左右人物上半身可见，中间紫色人形轮廓较小。视角略微仰视，强调上方发光天花板的压迫感。画面以深紫色和黑色为主调，人物面部和衣物受上方紫光照射，形成明暗对比，中间轮廓发出强烈辉光，整体光色层次丰富，营造出神秘氛围。","prompt":"昏暗室内场景，两名女性人物分列画面左右两侧，仅上半身可见，左侧人物穿着深色上衣，右侧人物佩戴头饰。画面正中央立着一个较小的紫色发光人形轮廓，发出强烈辉光。上方是大面积的紫色发光天花板，由网格状结构组成，向下投射出冷冽的紫色光线。四周环境几乎完全黑暗，仅有人物面部和衣物受光，形成强烈的明暗对比。整体色调以深紫和黑色为主，营造出神秘、压抑的视觉氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:17:58+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/34 (641).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.462,"observed_resolution":"normal","observation_limits":[],"id":"VP-62121fe7fceda035","origin":"visual"},{"work_id":"src-7627118d53bd4cf9","frame_id":"FG-94d1a68df9e62bab","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (622).jpg","source_page":"https://film-grab.com/2015/06/19/lost-river/","scene":"夜色中一座巨大的石砌建筑，正门上方雕刻着狰狞的鬼脸，窗户透出粉紫色光芒。建筑前停着一辆深色轿车，两侧路灯发出暖黄光，周围被黑暗包围。","analysis":"画面采用对称构图，建筑占据主体，鬼脸门楣位于视觉中心。轿车位于前景下方，与建筑形成大小对比。路灯分列两侧，形成引导线。整体明暗对比强烈，建筑内部粉紫光与外部暖黄路灯光形成冷暖色温层次，周围大面积黑暗增强了神秘压抑的氛围。","prompt":"夜色中的哥特式石砌建筑，正门上方雕刻着巨大的狰狞鬼脸浮雕，双眼深陷，嘴巴大张。建筑窗户透出粉紫色光芒，与外部黑暗形成对比。建筑前方停着一辆深色轿车，车身轮廓在暗处若隐若现。两侧各有一盏双头路灯，发出暖黄色光芒，照亮了建筑底部的石墙。周围树木在黑暗中形成剪影，整体画面色调阴冷，明暗对比强烈，营造出神秘压抑的恐怖氛围。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:18:09+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/47 (622).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.337,"observed_resolution":"normal","observation_limits":[],"id":"VP-a13af53ebd267864","origin":"visual"},{"work_id":"src-7627118d53bd4cf9","frame_id":"FG-ac4ce483c8edf27e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (570).jpg","source_page":"https://film-grab.com/2015/06/19/lost-river/","scene":"画面主体为一名男子的头部与肩部，他身体前倾，面部朝向下方。背景是带有网格线条的墙面，前景下方有一个模糊的红色发光物体。","analysis":"构图采用倾斜视角，人物占据画面上半部分，头部低垂，视线向下。人物仅可见头部、颈部及肩部，身穿浅色衣物。环境背景为带有黑色网格线的浅色墙面，占据右侧及背景区域。整体光线昏暗，笼罩在紫色与蓝色的冷色调中，前景的红色发光体形成强烈的色彩对比，营造出一种压抑且神秘的视觉氛围。","prompt":"这是一张倾斜视角的静帧画面，整体笼罩在浓郁的紫色与蓝色冷调光线下。画面上方是一名男子的头部与肩部特写，他身穿浅色衬衫，身体大幅度前倾，面部朝向左下方，神情显得凝重或专注。背景是带有黑色网格线条的浅色墙面，线条在透视中延伸。画面下方前景处有一个模糊的、边缘发光的红色不规则物体，形状类似某种灯具或标志，其鲜艳的红色与背景的冷紫色形成强烈反差。人物面部处于阴影中，细节模糊，整体画面呈现出一种压抑、神秘且具有电影质感的视觉风格。","verification":"观图待人工核","selection":"来源画面均匀采样，代表性待人工精选","model":"Qwen3.8-27B-FP8","created":"2026-10-14T14:18:20+08:00","analysis_kind":"模型观图草稿","prompt_kind":"基于源画面的创作改写","instruction_version":"film-still-observation-v2.1-single-hd-conservative","timecode":null,"camera_movement":"静帧无法判定","observed_image_url":"https://film-grab.com/wp-content/uploads/photo-gallery/60 (570).jpg","observed_dimensions":[1280,532],"source_thumbnail_dimensions":[500,208],"source_image_match_mae":0.548,"observed_resolution":"normal","observation_limits":[],"id":"VP-0559ef1d08f54572","origin":"visual"}]};